using EnterpriseERP.Domain.Exceptions;
using EnterpriseERP.Application.Common.Interfaces.Repositories; using EnterpriseERP.Domain.Entities.HR; using MediatR;  namespace EnterpriseERP.Application.Features.HR.Commands.AddDeduction;  public class AddDeductionCommandHandler : IRequestHandler<AddDeductionCommand, Guid> {     private readonly IGenericRepository<EmployeeDeduction> _deductionRepo;     private readonly IGenericRepository<Employee> _employeeRepo;     private readonly IUnitOfWork _unitOfWork;      public AddDeductionCommandHandler(         IGenericRepository<EmployeeDeduction> deductionRepo,         IGenericRepository<Employee> employeeRepo,         IUnitOfWork unitOfWork)     {         _deductionRepo = deductionRepo;         _employeeRepo = employeeRepo;         _unitOfWork = unitOfWork;     }      public async Task<Guid> Handle(AddDeductionCommand request, CancellationToken cancellationToken)     {         /* Validate employee exists and is active          */ var employee = await _employeeRepo.GetByIdAsync(request.EmployeeId)             ?? throw new HRDomainException($"Employee {request.EmployeeId} not found.");          if (!employee.IsActive)             throw new HRDomainException($"Cannot add deductions to inactive employee: {employee.FirstName} {employee.LastName}.");          if (request.Amount <= 0)             throw new HRDomainException("Deduction amount must be greater than zero.");          var deduction = new EmployeeDeduction         {             EmployeeId = request.EmployeeId,             DeductionType = request.DeductionType,             Description = request.Description,             Amount = request.Amount,             Year = request.Year,             Month = request.Month,             IsApplied = false,             CreatedAt = DateTime.UtcNow         };          await _deductionRepo.AddAsync(deduction);         await _unitOfWork.SaveChangesAsync(cancellationToken);          return deduction.Id;     } }

